function getTargetBaseDir(target, cwd) {
  if (target === 'project') {
    return join(cwd, '.agents', 'skills')
  }

  const a =
    getAgentByFlag(target) ||
    agents.find((candidate) => candidate.name === target)

  const baseDir = a ? a.getDir() : getAgentsDir()

  return rebaseToCwd(baseDir, cwd)
}
